#!/usr/bin/env python3
import sys
import json
import re

PREFIX_MAP = {
    "lisbon": "LIS",
    "porto": "OPO",
    "faro": "FAO",
    "braga": "BRG",
}

# Invoice number regex: PREFIX-YYYY-NNNNN
INV_RE = re.compile(
    r'^(?P<prefix>LIS|OPO|FAO|BRG)-'
    r'(?P<year>[2-9][0-9]{3})-'
    r'(?P<seq>(?!00000)[0-9]{5})$'
)

def refuse():
    """Terminate with status 2 and no stdout output."""
    sys.exit(2)

def main():
    try:
        raw = sys.stdin.buffer.read()
        text = raw.decode("utf-8")
    except Exception:
        refuse()

    try:
        data = json.loads(text)
    except Exception:
        refuse()

    if not isinstance(data, dict):
        refuse()

    # Required fields
    if "branch" not in data or "year" not in data or "previous" not in data:
        refuse()

    branch = data["branch"]
    year = data["year"]
    previous = data["previous"]

    if not isinstance(branch, str) or branch not in PREFIX_MAP:
        refuse()

    if not isinstance(year, int) or not (2000 <= year <= 9999):
        refuse()

    if previous is not None and not isinstance(previous, str):
        refuse()

    prefix = PREFIX_MAP[branch]
    next_seq = None

    if previous is None:
        next_seq = 1
    else:
        m = INV_RE.match(previous)
        if not m:
            refuse()

        prev_prefix = m.group("prefix")
        if prev_prefix != prefix:
            refuse()

        prev_year = int(m.group("year"))
        if prev_year > year:
            refuse()

        prev_seq = int(m.group("seq"))

        if prev_year < year:
            next_seq = 1
        else:  # same year
            if prev_seq == 99999:
                refuse()
            next_seq = prev_seq + 1

    if next_seq is None or next_seq > 99999:
        refuse()

    number = f"{prefix}-{year:04d}-{next_seq:05d}"
    output = {"number": number, "sequence": next_seq}
    sys.stdout.write(json.dumps(output, separators=(",", ":")))
    sys.exit(0)

if __name__ == "__main__":
    main()
